import { Controller, Get, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 메시지 구분은 항상 CHAT (BEHAVIOR.md 값의 출처)
const MESSAGE_TYPE = 'CHAT';
// 가정: 목록 크기 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function idOf(value: unknown, label: string): string {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value.trim())) {
    return value.trim();
  }
  throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
}

function hasValue(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}

function countOf(value: unknown, fallback: number, label: string): number {
  if (!hasValue(value)) {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr03602Controller {
  @Post('/messenger-messages')
  @HttpCode(200)
  async createMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const roomId = idOf(data['messengerRoomId'], '대화방 ID');
    const content = typeof data['content'] === 'string' ? data['content'].trim() : '';
    if (content === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 내용을 입력해 주세요.');
    }
    const replyId = hasValue(data['replyToMessageId']) ? idOf(data['replyToMessageId'], '답장 원본 메시지 ID') : null;
    return transaction(async (db) => {
      const rooms = await db.query(
        'SELECT messenger_room_id FROM messenger_room WHERE messenger_room_id = CAST(:roomId AS bigint)',
        { roomId },
      );
      if (rooms.length === 0) {
        throw new ApiError(404, 'MESSENGER_ROOM_NOT_FOUND', '대화방을 찾을 수 없습니다.');
      }
      if (replyId !== null) {
        const origin = await db.query(
          'SELECT messenger_message_id FROM messenger_message WHERE messenger_message_id = CAST(:replyId AS bigint)',
          { replyId },
        );
        if (origin.length === 0) {
          throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '답장할 원본 메시지를 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        'INSERT INTO messenger_message (messenger_room_id, sender_id, reply_to_message_id, message_type, content, sent_at, created_at, updated_at) '
          + 'VALUES (CAST(:roomId AS bigint), CAST(:userId AS bigint), CAST(:replyId AS bigint), :messageType, :content, now(), now(), now()) '
          + 'RETURNING messenger_message_id AS "messengerMessageId", sent_at AS "sentAt"',
        { roomId, userId: user.id, replyId, messageType: MESSAGE_TYPE, content },
      );
      return rows[0];
    });
  }

  @Post('/messenger-messages/:messengerMessageId/forward')
  @HttpCode(200)
  async forwardMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const sourceId = idOf(req.params['messengerMessageId'], '메시지 ID');
    const data = checks.inputOf(req.body);
    const roomId = hasValue(data['targetRoomId']) ? idOf(data['targetRoomId'], '대화방 ID') : null;
    let employeeIds: string[] = [];
    if (hasValue(data['targetEmployeeIds'])) {
      if (!Array.isArray(data['targetEmployeeIds'])) {
        throw new ApiError(400, 'VALIDATION_FAILED', '전달받을 사용자 목록 형식이 올바르지 않습니다.');
      }
      const ids = data['targetEmployeeIds'].map((v: unknown) => idOf(v, '사용자 ID'));
      employeeIds = Array.from(new Set(ids));
    }
    return transaction(async (db) => {
      const sources = await db.query(
        'SELECT content AS "content" FROM messenger_message WHERE messenger_message_id = CAST(:sourceId AS bigint)',
        { sourceId },
      );
      if (sources.length === 0) {
        throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '전달할 메시지를 찾을 수 없습니다.');
      }
      if (roomId === null && employeeIds.length === 0) {
        throw new ApiError(422, 'FORWARD_TARGET_REQUIRED', '전달받을 대화방 또는 사용자를 지정해 주세요.');
      }
      const content = sources[0].content;
      if (roomId !== null) {
        const rooms = await db.query(
          'SELECT messenger_room_id FROM messenger_room WHERE messenger_room_id = CAST(:roomId AS bigint)',
          { roomId },
        );
        if (rooms.length === 0) {
          throw new ApiError(404, 'MESSENGER_ROOM_NOT_FOUND', '전달받을 대화방을 찾을 수 없습니다.');
        }
      }
      for (const employeeId of employeeIds) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (found.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '전달받을 사용자를 찾을 수 없습니다.');
        }
      }
      let firstId: number | null = null;
      if (roomId !== null) {
        const rows = await db.query(
          'INSERT INTO messenger_message (messenger_room_id, sender_id, message_type, content, sent_at, created_at, updated_at) '
            + 'VALUES (CAST(:roomId AS bigint), CAST(:userId AS bigint), :messageType, :content, now(), now(), now()) '
            + 'RETURNING messenger_message_id AS "messengerMessageId"',
          { roomId, userId: user.id, messageType: MESSAGE_TYPE, content },
        );
        firstId = rows[0].messengerMessageId;
      }
      if (employeeIds.length > 0) {
        const rows = await db.query(
          'INSERT INTO messenger_message (sender_id, message_type, content, sent_at, created_at, updated_at) '
            + 'VALUES (CAST(:userId AS bigint), :messageType, :content, now(), now(), now()) '
            + 'RETURNING messenger_message_id AS "messengerMessageId"',
          { userId: user.id, messageType: MESSAGE_TYPE, content },
        );
        const newId = rows[0].messengerMessageId;
        for (const employeeId of employeeIds) {
          await db.execute(
            'INSERT INTO messenger_message_recipient (messenger_message_id, recipient_id, read_status, created_at, updated_at) '
              + 'VALUES (CAST(:newId AS bigint), CAST(:employeeId AS bigint), :readStatus, now(), now())',
            { newId, employeeId, readStatus: '안읽음' },
          );
        }
        if (firstId === null) {
          firstId = newId;
        }
      }
      return { messengerMessageId: firstId };
    });
  }

  @Get('/messenger-message-recipients')
  async listMessengerMessageRecipients(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const messageId = idOf(query['messengerMessageId'], '메시지 ID');
    const page = countOf(query['page'], 0, '쪽 번호');
    const size = Math.min(Math.max(countOf(query['size'], DEFAULT_SIZE, '쪽 크기'), 1), MAX_SIZE);
    return transaction(async (db) => {
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM messenger_message_recipient WHERE messenger_message_id = CAST(:messageId AS bigint)',
        { messageId },
      );
      const items = await db.query(
        'SELECT recipient_id AS "recipientId", read_status AS "readStatus", read_at AS "readAt" '
          + 'FROM messenger_message_recipient WHERE messenger_message_id = CAST(:messageId AS bigint) '
          + 'ORDER BY messenger_message_recipient_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { messageId, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/messenger-messages/:messengerMessageId/read')
  @HttpCode(200)
  async readMessengerMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = idOf(req.params['messengerMessageId'], '메시지 ID');
    return transaction(async (db) => {
      const messages = await db.query(
        'SELECT messenger_message_id FROM messenger_message WHERE messenger_message_id = CAST(:messageId AS bigint)',
        { messageId },
      );
      if (messages.length === 0) {
        throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '수신 대상 메시지를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE messenger_message_recipient SET read_status = :readStatus, read_at = COALESCE(read_at, now()), updated_at = now() '
          + 'WHERE messenger_message_id = CAST(:messageId AS bigint) AND recipient_id = CAST(:userId AS bigint) '
          + 'RETURNING read_status AS "readStatus"',
        { readStatus: '읽음', messageId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MESSENGER_MESSAGE_NOT_FOUND', '수신 대상 메시지를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

