import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  NumberInput,
  Pager,
  RefName,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const EMPTY: Page = { items: [], page: 0, size: 20, total: 0 };

function CreateForm({ role, replyTo, onDone }: { role: string; replyTo: unknown; onDone: (row: Row) => void }) {
  const [roomId, setRoomId] = useState<number | string>('');
  const [content, setContent] = useState('');
  const [replyId, setReplyId] = useState<number | string>(replyTo === undefined || replyTo === null ? '' : (replyTo as number));
  return (
    <Form
      submit='보내기'
      onSubmit={async () => {
        if (roomId === '' || content.trim() === '') {
          throw new Error('대화방과 메시지 내용을 입력해 주세요.');
        }
        const res = await call('POST', '/messenger-messages', role, {
          messengerRoomId: roomId,
          content,
          replyToMessageId: replyId === '' ? undefined : replyId,
        });
        onDone({ ...res, messengerRoomId: roomId, content });
      }}
    >
      <Field label='대화방 ID' required>
        <LookupSelect table='messenger_room' role={role} value={roomId} onChange={setRoomId} />
      </Field>
      <Field label='답장 원본 메시지 ID' hint='답장할 때만 입력합니다.'>
        <NumberInput value={replyId} onChange={setReplyId} />
      </Field>
      <Field label='메시지 내용' required wide>
        <TextInput value={content} onChange={setContent} multiline />
      </Field>
    </Form>
  );
}

function ForwardForm({ role, source, onDone }: { role: string; source: Row; onDone: () => void }) {
  const [roomId, setRoomId] = useState<number | string>('');
  const [employees, setEmployees] = useState<(number | string)[]>([]);
  return (
    <Form
      submit='전달하기'
      note='선택한 대화방과 사용자에게 같은 내용이 새 메시지로 전달됩니다.'
      onSubmit={async () => {
        if (roomId === '' && employees.length === 0) {
          throw new Error('전달받을 대화방 또는 사용자를 지정해 주세요.');
        }
        await call('POST', '/messenger-messages/' + String(source['messengerMessageId']) + '/forward', role, {
          targetRoomId: roomId === '' ? undefined : roomId,
          targetEmployeeIds: employees,
        });
        onDone();
      }}
    >
      <Field label='전달받을 대화방 ID'>
        <LookupSelect table='messenger_room' role={role} value={roomId} onChange={setRoomId} />
      </Field>
      <Field label='전달받을 사용자 ID 목록' wide hint='사용자를 고르면 아래 목록에 추가됩니다.'>
        <div>
          <LookupSelect
            table='employee'
            role={role}
            value=''
            onChange={(v) => {
              if (v !== '' && !employees.includes(v)) {
                setEmployees([...employees, v]);
              }
            }}
          />
          {employees.map((id) => (
            <div key={String(id)}>
              <RefName table='employee' role={role} value={id} />
              <button type='button' className='ghost' onClick={() => setEmployees(employees.filter((e) => e !== id))}>
                빼기
              </button>
            </div>
          ))}
        </div>
      </Field>
    </Form>
  );
}

function ReadForm({ role, onDone }: { role: string; onDone: () => void }) {
  const [messageId, setMessageId] = useState<number | string>('');
  return (
    <Form
      submit='읽음 처리'
      onSubmit={async () => {
        if (messageId === '') {
          throw new Error('메시지 ID를 입력해 주세요.');
        }
        await call('POST', '/messenger-messages/' + String(messageId) + '/read', role, {});
        onDone();
      }}
    >
      <Field label='메시지 ID' required>
        <NumberInput value={messageId} onChange={setMessageId} />
      </Field>
    </Form>
  );
}

export default function FnSfr03602Page({ role, notify }: PageProps) {
  const [sent, setSent] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'create' | 'forward' | 'read'>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [filterId, setFilterId] = useState<number | string>('');
  const [appliedId, setAppliedId] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);

  const recipients = useData<Page>(async () => {
    if (appliedId === '') {
      return EMPTY;
    }
    return call<Page>('GET', '/messenger-message-recipients', role, undefined, {
      messengerMessageId: appliedId,
      page: pageNo,
      size: 20,
    });
  }, [appliedId, pageNo, role]);

  const close = () => {
    setMode('');
    setTarget(null);
  };

  const showRecipients = (id: unknown) => {
    setFilterId(id as number);
    setAppliedId(id as number);
    setPageNo(0);
  };

  const page = recipients.data ?? EMPTY;

  return (
    <div className='doc'>
      <section className='box'>
        <h2>보낸 메시지</h2>
        <Band total={sent.length}>
          <button type='button' onClick={() => { setTarget(null); setMode('create'); }}>메시지 보내기</button>
          <button type='button' className='ghost' onClick={() => setMode('read')}>읽음 처리</button>
        </Band>
        <DataTable
          rows={sent}
          empty='아직 보낸 메시지가 없습니다. 메시지 보내기를 눌러 첫 메시지를 보내 보세요.'
          columns={[
            { key: 'messengerMessageId', label: '메시지 ID' },
            { key: 'messengerRoomId', label: '대화방', render: (r) => <RefName table='messenger_room' role={role} value={r['messengerRoomId']} /> },
            { key: 'content', label: '메시지 내용' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r['sentAt']} time /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  <button type='button' className='ghost' onClick={() => { setTarget(r); setMode('create'); }}>답장</button>
                  <button type='button' className='ghost' onClick={() => { setTarget(r); setMode('forward'); }}>전달</button>
                  <button type='button' className='ghost' onClick={() => showRecipients(r['messengerMessageId'])}>수신 현황</button>
                </span>
              ),
            },
          ]}
        />
      </section>

      <section className='box'>
        <h2>수신 확인</h2>
        <Filters
          onSearch={() => { setAppliedId(filterId); setPageNo(0); }}
          onReset={() => { setFilterId(''); setAppliedId(''); setPageNo(0); }}
        >
          <Field label='메시지 ID' required>
            <NumberInput value={filterId} onChange={setFilterId} />
          </Field>
        </Filters>
        <DataTable
          rows={page.items}
          empty='메시지 ID를 입력해 조회하면 수신자별 읽음 상태가 보입니다.'
          columns={[
            { key: 'recipientId', label: '수신자 ID', render: (r) => <RefName table='employee' role={role} value={r['recipientId']} /> },
            { key: 'readStatus', label: '읽음 상태', render: (r) => <Badge value={r['readStatus']} /> },
            { key: 'readAt', label: '읽은 일시', render: (r) => <DateText value={r['readAt']} time /> },
          ]}
        />
        <Pager page={page.page} size={page.size} total={page.total} onPage={setPageNo} />
      </section>

      {mode === 'create' && (
        <Drawer title={target ? '답장 보내기' : '메시지 보내기'} onClose={close}>
          <CreateForm
            role={role}
            replyTo={target ? target['messengerMessageId'] : undefined}
            onDone={(row) => {
              setSent([row, ...sent]);
              close();
              notify('메시지를 보냈습니다.');
            }}
          />
        </Drawer>
      )}
      {mode === 'forward' && target && (
        <Drawer title='메시지 전달' onClose={close}>
          <ForwardForm
            role={role}
            source={target}
            onDone={() => {
              close();
              notify('메시지를 전달했습니다.');
            }}
          />
        </Drawer>
      )}
      {mode === 'read' && (
        <Drawer title='메시지 읽음 처리' onClose={close}>
          <ReadForm
            role={role}
            onDone={() => {
              close();
              notify('읽음 처리했습니다.');
              recipients.reload();
            }}
          />
        </Drawer>
      )}
    </div>
  );
}
